"""One-shot offline analyzer and disposable native self-tests; no emulator attach."""
import argparse
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import sys
import time

from engine import ENGINE_VERSION, Image, Incompatible, driver_profile, pipe_identity, renderer_profile, require

ROOT = Path(__file__).resolve().parents[1]
# Updated only when a reviewed baseline is regenerated by the developer tool.
BASELINE_SHA256 = 'c58430a1bc3ec1b922a2e78541af8d1419fb335a59b4bca6edf796161a560541'


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def decode_profile(value):
    result = dict(value)
    result['guards'] = [(rva, bytes.fromhex(data)) for rva, data in value['guards']]
    if 'patches' in value:
        result['patches'] = [(rva, bytes.fromhex(old), bytes.fromhex(new)) for rva, old, new in value['patches']]
    return result


def analyze(kind, path, pipe=None):
    started = time.monotonic()
    raw = (ROOT / 'compatibility/baseline-v1.json').read_bytes()
    require(hashlib.sha256(raw).hexdigest() == BASELINE_SHA256, 'Compatibility baseline integrity check failed')
    baseline = json.loads(raw)
    require(baseline['schema'] == ENGINE_VERSION, 'Unknown compatibility baseline schema')
    image = Image(path)
    result = {'schema': ENGINE_VERSION, 'kind': kind, 'sha256': image.sha256,
              'baseline_sha256': BASELINE_SHA256, 'native_verified': False}
    if kind == 'pipe':
        require(pipe_identity(image) == baseline['pipe_identity'], 'fastpipe implementation changed; review required')
        result['compatible'] = True
    else:
        if kind == 'renderer':
            require(pipe is not None, 'Renderer adaptation requires its fastpipe pair')
            bridge = Image(pipe)
            profile = renderer_profile(image, bridge, baseline)
            result['pipe_sha256'] = bridge.sha256
            test = load('ld14_auto_native_test', ROOT / 'tests/test_native_patch.py')
            case = test.NativePatchTests()
            case.exercise(False, decode_profile(profile))
            case.exercise(True, decode_profile(profile))
            result['native_cases'] = 256
        else:
            profile = driver_profile(image, baseline)
            test = load('ld14_auto_cleanup_test', ROOT / 'tests/test_nvidia_cleanup.py')
            require(test.frida is not None, 'Frida is required for the automatic callback self-test')
            test.NvidiaCleanupTests().run_profile(image.sha256, decode_profile(profile))
            result['native_cases'] = 9
        result.update(compatible=True, native_verified=True, profile=profile)
    # A cached report is never an authority. Even this fresh result becomes
    # invalid if the installer replaced the file while the worker was running.
    require(hashlib.sha256(Path(path).read_bytes()).hexdigest() == image.sha256, 'Binary changed during analysis')
    if pipe is not None:
        require(hashlib.sha256(Path(pipe).read_bytes()).hexdigest() == result['pipe_sha256'], 'fastpipe changed during analysis')
    result['elapsed_seconds'] = round(time.monotonic() - started, 3)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--kind', choices=('pipe', 'renderer', 'driver'), required=True)
    parser.add_argument('--image', type=Path, required=True)
    parser.add_argument('--pipe', type=Path)
    parser.add_argument('--result', type=Path, required=True)
    args = parser.parse_args()
    try:
        result = analyze(args.kind, args.image, args.pipe)
        code = 0
    except Exception as error:
        result = {'schema': ENGINE_VERSION, 'kind': args.kind, 'compatible': False,
                  'native_verified': False, 'error': type(error).__name__ + ': ' + str(error)}
        code = 1
    temporary = args.result.with_suffix('.tmp')
    temporary.write_text(json.dumps(result, indent=2), encoding='utf-8')
    os.replace(temporary, args.result)
    return code


if __name__ == '__main__':
    sys.exit(main())
